const { useReducer, useState } = React;

function orderReducer(state, action) {
  if (action.type === 'pay' && state === 'ready') return 'paid';
  if (action.type === 'ship' && state === 'paid') return 'shipping';
  if (action.type === 'reset') return 'ready';
  return state;
}

function App() {
  const [open, setOpen] = useState(false);
  const [order, dispatch] = useReducer(orderReducer, 'ready');
  return (
    <main>
      <button type="button" onClick={() => setOpen(!open)}>패널 {open ? '닫기' : '열기'}</button>
      <button type="button" onClick={() => dispatch({ type: 'pay' })}>결제</button>
      <button type="button" onClick={() => dispatch({ type: 'ship' })}>배송</button>
      <button type="button" onClick={() => dispatch({ type: 'reset' })}>초기화</button>
      <p>패널: {String(open)} / 주문: {order}</p>
    </main>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<App />);

